example:
capability Edge = EdgeCache

service purges from queue("purges") {
    on message(path: String) -> Effect[QueueResult] given Edge {   // ✗ not the entrypoint the cache serves
        let purged <- Edge.purge([path])
        if purged { Ack } else { Retry("refused") }
    }
}

service operator from http {
    on POST("/purge/:hex") (hex: String) -> Effect[HttpResult[Bool]] by v: Visitor given Edge {   // ✓ purge from a service handler
        let purged <- Edge.purge(["/dl/\(hex)"])
        Ok(purged)
    }
}
